type Shape =
	| { kind: "circle"; r: number }
	| { kind: "rect"; w: number; h: number };

function area(s: Shape): number {
	switch (s.kind) {
		case "circle":
			return Math.PI * s.r ** 2;
		case "rect":
			return s.w * s.h;
		default: {
			const unreachable: never = s;
			return unreachable;
		}
	}
}

